import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { PDFDocument, StandardFonts, rgb } from "https://esm.sh/pdf-lib@1.17.1";
import {
  corsHeaders,
  createAdminClient,
  jsonResponse,
  requireFinancialLedgerAuthority,
} from "../_shared/financialLedgerAuthority.ts";

const PORTAL_URL = "https://b2b.oasisbaklawa.com";
const PROVIDER_TIMEOUT_MS = 10_000;
const LEDGER_KIND = "bi_monthly";
const LEDGER_BUCKET = "final-invoices";
const SIGNED_LEDGER_URL_TTL_SECONDS = 60 * 60;

type RunArgs = {
  company_id?: string | null;
  period_start?: string | null;
  period_end?: string | null;
  dry_run?: boolean;
};

type LedgerRow = {
  id: string;
  pdf_url: string | null;
  whatsapp_message_id: string | null;
  delivery_status: string;
  delivery_attempt_count: number;
};

function to91(raw: string): string {
  const digits = (raw || "").replace(/\D/g, "");
  if (digits.length === 10) return `91${digits}`;
  if (digits.length === 12 && digits.startsWith("91")) return digits;
  return digits;
}

function fmtINR(value: number): string {
  return "Rs. " + (value || 0).toLocaleString("en-IN", { maximumFractionDigits: 2 });
}

function fmtDate(value: string | null): string {
  if (!value) return "-";
  return new Date(value).toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

function parseDate(value: string | null | undefined): Date | null {
  if (!value) return null;
  const parsed = new Date(value);
  return Number.isFinite(parsed.getTime()) ? parsed : null;
}

function storageRef(path: string): string {
  return `storage:${LEDGER_BUCKET}/${path}`;
}

function storagePathFromRef(value: string | null): string | null {
  if (!value) return null;
  const canonicalPrefix = `storage:${LEDGER_BUCKET}/`;
  if (value.startsWith(canonicalPrefix)) return value.slice(canonicalPrefix.length);
  const legacyMarker = `/storage/v1/object/public/${LEDGER_BUCKET}/`;
  const markerIndex = value.indexOf(legacyMarker);
  if (markerIndex === -1) return null;
  const encodedPath = value.slice(markerIndex + legacyMarker.length).split("?")[0];
  try {
    return decodeURIComponent(encodedPath);
  } catch {
    return null;
  }
}

async function createLedgerSignedUrl(
  admin: ReturnType<typeof createAdminClient>,
  storedRef: string | null,
): Promise<string | null> {
  const path = storagePathFromRef(storedRef);
  if (!path) return null;
  const { data, error } = await admin.storage
    .from(LEDGER_BUCKET)
    .createSignedUrl(path, SIGNED_LEDGER_URL_TTL_SECONDS);
  if (error || !data?.signedUrl) {
    console.error("[generate-bi-monthly-ledger] signed URL creation failed", error?.message ?? "missing_signed_url");
    return null;
  }
  return data.signedUrl;
}

async function buildLedgerPdf(args: {
  businessName: string;
  periodStart: string;
  periodEnd: string;
  rows: { date: string; orderRef: string; status: string; amount: number }[];
  totalOutstanding: number;
}): Promise<Uint8Array> {
  const pdfDoc = await PDFDocument.create();
  const page = pdfDoc.addPage([595, 842]);
  const helv = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const bold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const champagne = rgb(0.72, 0.52, 0.04);
  const ink = rgb(0.13, 0.16, 0.22);
  const mute = rgb(0.45, 0.49, 0.55);
  const line = rgb(0.85, 0.87, 0.91);

  page.drawText("OASIS BAKLAWA", { x: 40, y: 790, size: 18, font: bold, color: ink });
  page.drawText("Bi-Monthly Account Statement", { x: 40, y: 770, size: 11, font: helv, color: mute });
  page.drawText("Account Statement", { x: 400, y: 790, size: 12, font: bold, color: champagne });
  page.drawText(`Period: ${fmtDate(args.periodStart)} - ${fmtDate(args.periodEnd)}`, { x: 400, y: 772, size: 9, font: helv, color: mute });
  page.drawLine({ start: { x: 40, y: 755 }, end: { x: 555, y: 755 }, thickness: 1, color: champagne });
  page.drawText("BILLED TO", { x: 40, y: 730, size: 8, font: bold, color: mute });
  page.drawText(args.businessName, { x: 40, y: 712, size: 13, font: bold, color: ink });
  page.drawText("We have shared this gentle account summary for your kind reconciliation. If everything aligns,", { x: 40, y: 685, size: 9, font: helv, color: mute });
  page.drawText("no action is needed. If you spot any discrepancy, kindly reply 'Request Correction' on WhatsApp.", { x: 40, y: 672, size: 9, font: helv, color: mute });

  let y = 640;
  page.drawRectangle({ x: 40, y: y - 4, width: 515, height: 22, color: rgb(0.96, 0.97, 0.99) });
  page.drawText("DATE", { x: 50, y: y + 4, size: 9, font: bold, color: ink });
  page.drawText("ORDER REF", { x: 145, y: y + 4, size: 9, font: bold, color: ink });
  page.drawText("STATUS", { x: 305, y: y + 4, size: 9, font: bold, color: ink });
  page.drawText("ORDER VALUE", { x: 470, y: y + 4, size: 9, font: bold, color: ink });
  y -= 28;

  for (const row of args.rows) {
    if (y < 80) {
      page.drawText("(continued on next page)", { x: 40, y: 60, size: 8, font: helv, color: mute });
      break;
    }
    page.drawText(fmtDate(row.date), { x: 50, y, size: 9, font: helv, color: ink });
    page.drawText(row.orderRef, { x: 145, y, size: 9, font: helv, color: ink });
    page.drawText(row.status, { x: 305, y, size: 9, font: helv, color: mute });
    page.drawText(fmtINR(row.amount), { x: 480, y, size: 9, font: bold, color: ink });
    y -= 16;
    page.drawLine({ start: { x: 40, y: y + 8 }, end: { x: 555, y: y + 8 }, thickness: 0.3, color: line });
  }

  if (args.rows.length === 0) {
    page.drawText("No orders in this period.", { x: 50, y, size: 10, font: helv, color: mute });
    y -= 20;
  }

  y -= 10;
  page.drawLine({ start: { x: 40, y: y + 6 }, end: { x: 555, y: y + 6 }, thickness: 1, color: champagne });
  page.drawText("CURRENT TOTAL OUTSTANDING", { x: 50, y: y - 12, size: 10, font: bold, color: ink });
  page.drawText(fmtINR(args.totalOutstanding), { x: 460, y: y - 12, size: 12, font: bold, color: champagne });
  page.drawText("Thank you for your continued partnership with Oasis Baklawa.", { x: 40, y: 50, size: 9, font: helv, color: mute });
  page.drawText(PORTAL_URL, { x: 40, y: 36, size: 8, font: helv, color: champagne });
  return await pdfDoc.save();
}

async function sendWhatsAppPdf(phone: string, businessName: string, pdfUrl: string) {
  const apiKey = Deno.env.get("CLICK2API_API_KEY");
  if (!apiKey) return { ok: false, id: null, error: "provider_not_configured" };
  const accessToken = Deno.env.get("CLICK2API_ACCESS_TOKEN");
  const to = to91(phone);
  if (!/^91\d{10}$/.test(to)) return { ok: false, id: null, error: "invalid_phone" };

  const message = `Dear ${businessName},\n\nAs part of our gentle bi-monthly reconciliation, here is your account statement for the last 15 days.\n\nKindly review at your convenience. If everything matches, no reply is needed.\nIf something seems off, simply reply *Request Correction* and our Oasis team will review it together with you.\n\nSecure statement link (expires in 1 hour): ${pdfUrl}\n\nWith warm regards,\n— Team Oasis Baklawa`;
  const providerHeaders = {
    "Content-Type": "application/json",
    apikey: apiKey,
    ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
  };

  try {
    const response = await fetch("https://crm.click2api.in/api/v1/messages", {
      method: "POST",
      signal: AbortSignal.timeout(PROVIDER_TIMEOUT_MS),
      headers: providerHeaders,
      body: JSON.stringify({
        messaging_product: "whatsapp",
        to,
        type: "document",
        document: { link: pdfUrl, filename: "Oasis-Account-Statement.pdf", caption: message },
      }),
    });
    const payload = await response.json().catch(() => ({}));
    if (response.ok) return { ok: true, id: payload?.messages?.[0]?.id || payload?.id || "sent", error: null };
    // Only a definite provider rejection makes a second text send safe.
  } catch (error) {
    console.warn("[generate-bi-monthly-ledger] document delivery outcome uncertain", error instanceof Error ? error.name : "unknown");
    return { ok: false, id: null, error: error instanceof DOMException && error.name === "TimeoutError" ? "provider_timeout_uncertain" : "provider_outcome_uncertain" };
  }

  try {
    const response = await fetch("https://crm.click2api.in/api/v1/messages", {
      method: "POST",
      signal: AbortSignal.timeout(PROVIDER_TIMEOUT_MS),
      headers: providerHeaders,
      body: JSON.stringify({ messaging_product: "whatsapp", to, type: "text", text: { body: message } }),
    });
    const payload = await response.json().catch(() => ({}));
    return response.ok
      ? { ok: true, id: payload?.messages?.[0]?.id || payload?.id || "sent", error: null }
      : { ok: false, id: null, error: "provider_rejected" };
  } catch (error) {
    console.warn("[generate-bi-monthly-ledger] fallback delivery outcome uncertain", error instanceof Error ? error.name : "unknown");
    return { ok: false, id: null, error: "provider_outcome_uncertain" };
  }
}

async function deliverLedger(
  admin: ReturnType<typeof createAdminClient>,
  ledger: LedgerRow,
  phone: string | null,
  businessName: string,
): Promise<Record<string, unknown>> {
  if (!phone) {
    await admin.from("bi_monthly_ledgers").update({ delivery_status: "skipped", delivery_lease_until: null, last_delivery_error: "phone_unavailable" }).eq("id", ledger.id);
    return { ok: true, delivery_status: "skipped", reason: "phone_unavailable" };
  }
  if (!ledger.pdf_url) {
    await admin.from("bi_monthly_ledgers").update({ delivery_status: "failed", delivery_lease_until: null, last_delivery_error: "pdf_reference_unavailable" }).eq("id", ledger.id);
    return { ok: false, delivery_status: "failed", error: "pdf_reference_unavailable" };
  }

  const { data: claimed, error: claimError } = await admin.rpc("claim_bi_monthly_ledger_delivery", { _ledger_id: ledger.id, _lease_seconds: 120 });
  if (claimError) {
    console.error("[generate-bi-monthly-ledger] delivery claim failed", claimError.message);
    return { ok: false, delivery_status: "failed", error: "delivery_claim_failed" };
  }
  if (claimed !== true) return { ok: true, duplicate_suppressed: true, delivery_status: "sending" };

  const signedPdfUrl = await createLedgerSignedUrl(admin, ledger.pdf_url);
  if (!signedPdfUrl) {
    await admin.from("bi_monthly_ledgers").update({ delivery_status: "failed", delivery_lease_until: null, last_delivery_error: "signed_url_unavailable" }).eq("id", ledger.id);
    return { ok: false, delivery_status: "failed", error: "signed_url_unavailable" };
  }

  const delivery = await sendWhatsAppPdf(phone, businessName, signedPdfUrl);
  if (delivery.ok) {
    const sentAt = new Date().toISOString();
    const { error: finalizeError } = await admin.from("bi_monthly_ledgers").update({
      delivery_status: "sent",
      delivery_lease_until: null,
      last_delivery_error: null,
      whatsapp_message_id: delivery.id,
      sent_at: sentAt,
      status: "sent",
    }).eq("id", ledger.id);
    if (finalizeError) {
      console.error("[generate-bi-monthly-ledger] sent delivery could not be finalized", finalizeError.message);
      return { ok: false, delivery_status: "sending", error: "delivery_finalization_uncertain", manual_reconciliation_required: true };
    }
    return { ok: true, delivery_status: "sent", whatsapp_message_id: delivery.id };
  }

  if (String(delivery.error || "").includes("uncertain")) {
    await admin.from("bi_monthly_ledgers").update({ last_delivery_error: delivery.error }).eq("id", ledger.id);
    return { ok: false, delivery_status: "sending", error: delivery.error, manual_reconciliation_required: true };
  }

  const { error: failError } = await admin.from("bi_monthly_ledgers").update({
    delivery_status: "failed",
    delivery_lease_until: null,
    last_delivery_error: delivery.error || "provider_failed",
  }).eq("id", ledger.id);
  if (failError) {
    console.error("[generate-bi-monthly-ledger] failed delivery could not be finalized", failError.message);
    return { ok: false, delivery_status: "sending", error: "delivery_finalization_uncertain", manual_reconciliation_required: true };
  }
  return { ok: false, delivery_status: "failed", error: delivery.error || "provider_failed" };
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: corsHeaders() });
  if (req.method !== "POST") return jsonResponse({ ok: false, error: "method_not_allowed" }, 405);

  const supabaseUrl = Deno.env.get("SUPABASE_URL") || "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";
  const publicKey = Deno.env.get("SUPABASE_ANON_KEY") || Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || "";
  if (!supabaseUrl || !serviceRoleKey) return jsonResponse({ ok: false, error: "service_unavailable" }, 503);

  const authority = await requireFinancialLedgerAuthority(req, supabaseUrl, serviceRoleKey, publicKey);
  if (!authority.ok) return jsonResponse({ ok: false, error: authority.error }, authority.status);
  const admin = createAdminClient(supabaseUrl, serviceRoleKey);

  let body: RunArgs = {};
  try { body = (await req.json()) as RunArgs; } catch { body = {}; }

  const today = new Date();
  const requestedEnd = parseDate(body.period_end);
  const requestedStart = parseDate(body.period_start);
  if ((body.period_end && !requestedEnd) || (body.period_start && !requestedStart)) return jsonResponse({ ok: false, error: "invalid_period" }, 400);
  const periodEnd = requestedEnd ?? today;
  const periodStart = requestedStart ?? new Date(periodEnd.getTime() - 14 * 24 * 3600 * 1000);
  if (periodStart.getTime() > periodEnd.getTime()) return jsonResponse({ ok: false, error: "invalid_period" }, 400);

  const periodStartIso = periodStart.toISOString().slice(0, 10);
  const periodEndIso = periodEnd.toISOString().slice(0, 10);

  try {
    let companies: { id: string; business_name: string; phone: string | null; total_outstanding: number | null }[] = [];
    if (body.company_id) {
      const { data, error } = await admin.from("companies").select("id, business_name, phone, payment_terms, total_outstanding").eq("id", body.company_id).maybeSingle();
      if (error) throw error;
      if (data) companies = [data as typeof companies[number]];
    } else {
      const { data, error } = await admin.from("companies").select("id, business_name, phone, payment_terms, total_outstanding").eq("payment_terms", "credit");
      if (error) throw error;
      companies = (data || []) as typeof companies;
    }

    if (body.dry_run === true) return jsonResponse({ ok: true, dry_run: true, authorized_as: authority.kind, target_companies: companies.length, period_start: periodStartIso, period_end: periodEndIso });

    const results: Record<string, unknown>[] = [];
    let generated = 0;
    for (const company of companies) {
      const { data: existing, error: existingError } = await admin.from("bi_monthly_ledgers")
        .select("id, pdf_url, whatsapp_message_id, delivery_status, delivery_attempt_count")
        .eq("company_id", company.id).eq("period_start", periodStartIso).eq("period_end", periodEndIso).eq("ledger_kind", LEDGER_KIND).maybeSingle();
      if (existingError) throw existingError;
      if (existing) {
        const ledger = existing as LedgerRow;
        if (["sent", "skipped"].includes(ledger.delivery_status)) {
          results.push({ company_id: company.id, ok: true, duplicate_suppressed: true, ledger_id: ledger.id, delivery_status: ledger.delivery_status });
          continue;
        }
        if (ledger.delivery_status === "sending") {
          results.push({ company_id: company.id, ok: false, duplicate_suppressed: true, ledger_id: ledger.id, delivery_status: "sending", manual_reconciliation_required: true });
          continue;
        }
        const retry = await deliverLedger(admin, ledger, company.phone, company.business_name);
        results.push({ company_id: company.id, ledger_id: ledger.id, retried: true, ...retry });
        continue;
      }

      const { data: orders, error: ordersError } = await admin.from("orders")
        .select("id, status, sales_order_value, created_at").eq("company_id", company.id)
        .gte("created_at", `${periodStartIso}T00:00:00+05:30`).lte("created_at", `${periodEndIso}T23:59:59.999999+05:30`)
        .not("status", "in", "(draft,cart,cancelled)").order("created_at", { ascending: true });
      if (ordersError) throw ordersError;

      const rows = (orders || []).map((order: any) => ({
        date: order.created_at,
        orderRef: `SO-${String(order.id).slice(0, 8).toUpperCase()}`,
        status: String(order.status || "").replace(/_/g, " "),
        amount: Number(order.sales_order_value || 0),
      }));
      const totalOutstanding = Number(company.total_outstanding || 0);
      const pdfBytes = await buildLedgerPdf({ businessName: company.business_name, periodStart: periodStartIso, periodEnd: periodEndIso, rows, totalOutstanding });
      const path = `ledgers/${company.id}/${periodStartIso}_${periodEndIso}.pdf`;
      const { error: uploadError } = await admin.storage.from(LEDGER_BUCKET).upload(path, pdfBytes, { contentType: "application/pdf", upsert: true });
      if (uploadError) { results.push({ company_id: company.id, ok: false, error: "pdf_upload_failed" }); continue; }
      const pdfRef = storageRef(path);

      const { data: ledger, error: ledgerError } = await admin.from("bi_monthly_ledgers").insert({
        company_id: company.id,
        period_start: periodStartIso,
        period_end: periodEndIso,
        total_amount: totalOutstanding,
        order_count: rows.length,
        pdf_url: pdfRef,
        status: "generated",
        ledger_kind: LEDGER_KIND,
        delivery_status: "pending",
        delivery_attempt_count: 0,
        generated_by: authority.userId,
        sent_at: null,
      }).select("id, pdf_url, whatsapp_message_id, delivery_status, delivery_attempt_count").single();
      if (ledgerError) {
        if ((ledgerError as any).code === "23505") { results.push({ company_id: company.id, ok: true, duplicate_suppressed: true }); continue; }
        throw ledgerError;
      }

      generated += 1;
      const delivery = await deliverLedger(admin, ledger as LedgerRow, company.phone, company.business_name);
      results.push({ company_id: company.id, ledger_id: ledger.id, order_count: rows.length, total_outstanding: totalOutstanding, ...delivery });
    }

    return jsonResponse({ ok: true, generated, period_start: periodStartIso, period_end: periodEndIso, results });
  } catch (error) {
    console.error("[generate-bi-monthly-ledger] failure", error instanceof Error ? error.message : "unknown");
    return jsonResponse({ ok: false, error: "internal_error" }, 500);
  }
});

import {
  createClient,
  type SupabaseClient,
} from "npm:@supabase/supabase-js@2.45.0";

export type LedgerAuthority =
  | { ok: true; kind: "cron" | "user"; userId: string | null }
  | { ok: false; status: 401 | 403 | 500; error: string };

type AdminClient = SupabaseClient;

export function createAdminClient(
  supabaseUrl: string,
  serviceRoleKey: string,
): SupabaseClient {
  return createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false },
  });
}

export function jsonHeaders(): Record<string, string> {
  return {
    "Content-Type": "application/json",
    "Cache-Control": "no-store",
    "Pragma": "no-cache",
    "X-Content-Type-Options": "nosniff",
  };
}

export function corsHeaders(): Record<string, string> {
  return {
    ...jsonHeaders(),
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers":
      "authorization, x-client-info, apikey, content-type, x-oasis-cron-secret",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
  };
}

export function jsonResponse(
  body: Record<string, unknown>,
  status = 200,
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: corsHeaders(),
  });
}

export function bearerToken(req: Request): string | null {
  const value = req.headers.get("Authorization") ?? "";
  if (!value.startsWith("Bearer ")) return null;
  const token = value.slice(7).trim();
  return token || null;
}

export type FinancialLedgerAuthorityDeps = {
  verifyCronSecret: (
    candidate: string,
  ) => Promise<{ data: boolean | null; error: { message: string } | null }>;
  getUserIdFromToken: (
    token: string,
  ) => Promise<{ userId: string | null; invalid: boolean }>;
  isFinancialOperator: (
    userId: string,
  ) => Promise<{ allowed: boolean | null; error: { message: string } | null }>;
};

export async function resolveFinancialLedgerAuthority(
  req: Request,
  deps: FinancialLedgerAuthorityDeps,
  options: { publicKeyAvailable: boolean },
): Promise<LedgerAuthority> {
  const cronCandidate = req.headers.get("x-oasis-cron-secret")?.trim() ?? "";
  if (cronCandidate) {
    const { data, error } = await deps.verifyCronSecret(cronCandidate);
    if (error) {
      console.error(
        "[financial-ledger] cron authority lookup failed",
        error.message,
      );
      return { ok: false, status: 500, error: "authority_unavailable" };
    }
    return data === true
      ? { ok: true, kind: "cron", userId: null }
      : { ok: false, status: 403, error: "forbidden" };
  }

  const token = bearerToken(req);
  if (!token) return { ok: false, status: 401, error: "unauthorized" };
  if (!options.publicKeyAvailable) {
    console.error("[financial-ledger] public auth key unavailable");
    return { ok: false, status: 500, error: "authority_unavailable" };
  }

  const { userId, invalid } = await deps.getUserIdFromToken(token);
  if (invalid || !userId) {
    return { ok: false, status: 401, error: "unauthorized" };
  }

  const { allowed, error: roleError } = await deps.isFinancialOperator(userId);
  if (roleError) {
    console.error(
      "[financial-ledger] finance role lookup failed",
      roleError.message,
    );
    return { ok: false, status: 500, error: "authority_unavailable" };
  }
  if (allowed !== true) return { ok: false, status: 403, error: "forbidden" };

  return { ok: true, kind: "user", userId };
}

export async function requireFinancialLedgerAuthority(
  req: Request,
  supabaseUrl: string,
  serviceRoleKey: string,
  publicKey: string,
): Promise<LedgerAuthority> {
  const admin = createAdminClient(supabaseUrl, serviceRoleKey);

  return await resolveFinancialLedgerAuthority(
    req,
    {
      verifyCronSecret: async (candidate) => {
        const { data, error } = await admin.rpc(
          "verify_financial_ledger_cron_secret",
          { _candidate: candidate },
        );
        return { data, error };
      },
      getUserIdFromToken: async (token) => {
        const authClient = createClient(supabaseUrl, publicKey, {
          auth: { persistSession: false },
          global: { headers: { Authorization: `Bearer ${token}` } },
        });
        const { data: userData, error: userError } = await authClient.auth
          .getUser(token);
        const userId = userData.user?.id ?? null;
        return { userId, invalid: Boolean(userError || !userId) };
      },
      isFinancialOperator: async (userId) => {
        const { data, error } = await admin.rpc(
          "is_financial_ledger_operator",
          { _user_id: userId },
        );
        return { allowed: data, error };
      },
    },
    { publicKeyAvailable: Boolean(publicKey) },
  );
}
